type InvoiceStatus = 'Draft' | 'Submitted' | 'Approved' | 'Paid' | 'Overdue' | 'Cancelled';
type ExpenseCategory = 'Travel' | 'Meals' | 'Equipment' | 'Software' | 'Other';
type ExpenseStatus = 'Draft' | 'Submitted' | 'Approved' | 'Rejected' | 'Reimbursed';

interface Invoice {
  id: string;
  number: string;
  supplierId: string;
  supplier: string;
  issueDate: string;
  dueDate: string;
  amount: number;
  tax: number;
  status: InvoiceStatus;
  notes: string;
  totalCents: number;
  approvedBy?: string;
}

interface ExpenseClaimInput {
  id: string;
  employeeName: string;
  dateIncurred: string;
  category: ExpenseCategory;
  amount: number;
  receiptReference: string;
  status?: ExpenseStatus;
  decisionNote?: string;
}

interface ExpenseClaim {
  id: string;
  employeeName: string;
  dateIncurred: string;
  category: ExpenseCategory;
  amount: number;
  receiptReference: string;
  status: ExpenseStatus;
  decisionNote: string;
}

interface ValidationResult {
  valid: boolean;
  errors: string[];
}

interface Dashboard {
  totalOutstanding: number;
  totalOverdue: number;
  countByStatus: Record<string, number>;
  expensesAwaitingApproval: number;
  topSuppliers: { supplier: string; amount: number }[];
}

const STORE: { invoices: Invoice[]; claims: ExpenseClaim[] } = { invoices: [], claims: [] };

/**
 * Compute the age in whole days of an invoice relative to its due date.
 * Age is days since the due date; an invoice due today or in the future has age 0.
 * @param invoice the invoice to age
 * @param today the reference date
 * @returns number of days past due (0 when not yet due)
 */
// req-1
function computeAge(invoice: Invoice, today: Date): number {
  const due = Date.parse(invoice.dueDate + 'T00:00:00.000Z');
  const now = Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate());
  if (Number.isNaN(due)) {
    return 0;
  }
  const diff = Math.floor((now - due) / 86400000);
  return diff > 0 ? diff : 0;
}

/**
 * Compute an invoice due date from the issue date plus the supplier payment terms in days.
 * @param issueDate the date the invoice was issued
 * @param paymentTermsDays the supplier's payment terms in days (may be 0)
 * @returns the computed due date
 */
// req-4
function computeDueDate(issueDate: Date, paymentTermsDays: number): Date {
  const base = Date.UTC(issueDate.getUTCFullYear(), issueDate.getUTCMonth(), issueDate.getUTCDate());
  return new Date(base + paymentTermsDays * 86400000);
}

/**
 * Recompute the Overdue status of each invoice from its stored due date and status.
 * Paid and Cancelled invoices are never marked Overdue. Recompute is idempotent.
 * @param invoices the stored invoices
 * @param today the reference date used to judge overdue
 * @returns the recomputed invoices and the count transitioned to Overdue
 */
// req-6
function refreshOverdueStatuses(invoices: Invoice[], today: Date): { invoices: Invoice[]; changed: number } {
  const now = Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate());
  let changed = 0;
  const next: Invoice[] = invoices.map((inv: Invoice): Invoice => {
    const due = Date.parse(inv.dueDate + 'T00:00:00.000Z');
    const isTerminal = inv.status === 'Paid' || inv.status === 'Cancelled';
    if (isTerminal) {
      return { id: inv.id, number: inv.number, supplierId: inv.supplierId, supplier: inv.supplier, issueDate: inv.issueDate, dueDate: inv.dueDate, amount: inv.amount, tax: inv.tax, status: inv.status, notes: inv.notes, totalCents: inv.totalCents, approvedBy: inv.approvedBy };
    }
    const pastDue = !Number.isNaN(due) && now > due;
    if (pastDue && inv.status !== 'Overdue') {
      changed += 1;
      return { id: inv.id, number: inv.number, supplierId: inv.supplierId, supplier: inv.supplier, issueDate: inv.issueDate, dueDate: inv.dueDate, amount: inv.amount, tax: inv.tax, status: 'Overdue', notes: inv.notes, totalCents: inv.totalCents, approvedBy: inv.approvedBy };
    }
    return { id: inv.id, number: inv.number, supplierId: inv.supplierId, supplier: inv.supplier, issueDate: inv.issueDate, dueDate: inv.dueDate, amount: inv.amount, tax: inv.tax, status: inv.status, notes: inv.notes, totalCents: inv.totalCents, approvedBy: inv.approvedBy };
  });
  STORE.invoices = next;
  return { invoices: next, changed: changed };
}

/**
 * Validate a decision note for an expense rejection; must be at least 8 characters after trimming.
 * @param note the decision note text
 * @returns validation result with any errors
 */
// req-7
function validateDecisionNote(note: string): ValidationResult {
  const errors: string[] = [];
  const trimmed = typeof note === 'string' ? note.trim() : '';
  if (trimmed.length < 8) {
    errors.push('Decision note must be at least 8 characters.');
  }
  return { valid: errors.length === 0, errors: errors };
}

/**
 * Create and store a new expense claim in Draft or Submitted status.
 * @param input the raw expense claim input
 * @returns the persisted expense claim
 */
// req-7
async function createExpenseClaim(input: ExpenseClaimInput): Promise<ExpenseClaim> {
  const status: ExpenseStatus = input.status === 'Submitted' ? 'Submitted' : 'Draft';
  const claim: ExpenseClaim = {
    id: input.id,
    employeeName: String(input.employeeName),
    dateIncurred: String(input.dateIncurred),
    category: input.category,
    amount: input.amount,
    receiptReference: String(input.receiptReference),
    status: status,
    decisionNote: typeof input.decisionNote === 'string' ? input.decisionNote : ''
  };
  STORE.claims = STORE.claims.filter((c: ExpenseClaim): boolean => c.id !== claim.id).concat([claim]);
  return claim;
}

/**
 * Reject an expense claim; requires a decision note of at least 8 characters.
 * A rejected claim is never reimbursable and an approved claim cannot be re-approved.
 * @param id the expense claim id
 * @param note the rejection decision note
 * @returns the updated expense claim
 */
// req-7
async function rejectExpenseClaim(id: string, note: string): Promise<ExpenseClaim> {
  const check = validateDecisionNote(note);
  if (!check.valid) {
    throw new Error(check.errors.join(' '));
  }
  const found = STORE.claims.filter((c: ExpenseClaim): boolean => c.id === id)[0];
  if (!found) {
    throw new Error('Expense claim not found: ' + id);
  }
  if (found.status === 'Reimbursed') {
    throw new Error('A reimbursed claim cannot be rejected.');
  }
  const updated: ExpenseClaim = {
    id: found.id,
    employeeName: found.employeeName,
    dateIncurred: found.dateIncurred,
    category: found.category,
    amount: found.amount,
    receiptReference: found.receiptReference,
    status: 'Rejected',
    decisionNote: note.trim()
  };
  STORE.claims = STORE.claims.map((c: ExpenseClaim): ExpenseClaim => (c.id === id ? updated : c));
  return updated;
}

/**
 * Mark an approved expense claim as reimbursed. A rejected claim cannot be reimbursed.
 * @param id the expense claim id
 * @returns the updated expense claim
 */
// req-7
async function reimburseExpenseClaim(id: string): Promise<ExpenseClaim> {
  const found = STORE.claims.filter((c: ExpenseClaim): boolean => c.id === id)[0];
  if (!found) {
    throw new Error('Expense claim not found: ' + id);
  }
  if (found.status === 'Rejected') {
    throw new Error('A rejected claim cannot be reimbursed.');
  }
  if (found.status === 'Approved' || found.status === 'Submitted' || found.status === 'Draft') {
    const updated: ExpenseClaim = {
      id: found.id,
      employeeName: found.employeeName,
      dateIncurred: found.dateIncurred,
      category: found.category,
      amount: found.amount,
      receiptReference: found.receiptReference,
      status: 'Reimbursed',
      decisionNote: found.decisionNote
    };
    STORE.claims = STORE.claims.map((c: ExpenseClaim): ExpenseClaim => (c.id === id ? updated : c));
    return updated;
  }
  if (found.status === 'Reimbursed') {
    return found;
  }
  return found;
}

/**
 * Build the dashboard totals from stored invoices and claims, derived fresh per request.
 * @param invoices the stored invoices
 * @param claims the stored expense claims
 * @returns dashboard aggregates including top five suppliers by outstanding amount
 */
// req-9
function getDashboard(invoices: Invoice[], claims: ExpenseClaim[]): Dashboard {
  let totalOutstanding = 0;
  let totalOverdue = 0;
  const countByStatus: Record<string, number> = {
    Draft: 0,
    Submitted: 0,
    Approved: 0,
    Paid: 0,
    Overdue: 0,
    Cancelled: 0
  };
  const supplierTotals: Record<string, number> = {};
  for (let i = 0; i < invoices.length; i += 1) {
    const inv = invoices[i];
    if (countByStatus[inv.status] === undefined) {
      countByStatus[inv.status] = 0;
    }
    countByStatus[inv.status] += 1;
    const total = inv.amount + inv.tax;
    if (inv.status !== 'Paid' && inv.status !== 'Cancelled') {
      totalOutstanding += total;
      if (supplierTotals[inv.supplier] === undefined) {
        supplierTotals[inv.supplier] = 0;
      }
      supplierTotals[inv.supplier] += total;
      if (inv.status === 'Overdue') {
        totalOverdue += total;
      }
    }
  }
  let expensesAwaitingApproval = 0;
  for (let j = 0; j < claims.length; j += 1) {
    if (claims[j].status === 'Submitted') {
      expensesAwaitingApproval += 1;
    }
  }
  const suppliers: { supplier: string; amount: number }[] = [];
  const keys = Object.keys(supplierTotals);
  for (let k = 0; k < keys.length; k += 1) {
    suppliers.push({ supplier: keys[k], amount: supplierTotals[keys[k]] });
  }
  suppliers.sort((a: { supplier: string; amount: number }, b: { supplier: string; amount: number }): number => {
    if (b.amount !== a.amount) {
      return b.amount - a.amount;
    }
    return a.supplier < b.supplier ? -1 : a.supplier > b.supplier ? 1 : 0;
  });
  const topSuppliers = suppliers.slice(0, 5);
  return {
    totalOutstanding: totalOutstanding,
    totalOverdue: totalOverdue,
    countByStatus: countByStatus,
    expensesAwaitingApproval: expensesAwaitingApproval,
    topSuppliers: topSuppliers
  };
}
export { computeAge, computeDueDate, refreshOverdueStatuses, createExpenseClaim, rejectExpenseClaim, reimburseExpenseClaim, validateDecisionNote, getDashboard };

